import random, subprocess, tempfile
from pathlib import Path
SAMPLE_IN = '3\n2\n8 5\n3\n8 5 6\n3\n4 10 11\n'
SAMPLE_OUT = '2\n1\n2\n'
CASES = ['3\n2\n8 5\n3\n8 5 6\n3\n4 10 11\n', '4\n5\n765 4579 1663 7552 3918\n8\n7192 2348 3934 9321 7537 4372 1041 3289\n3\n1123 1760 4389\n6\n2772 9196 9924 5651 7219 5590\n', '2\n7\n9670 6434 3278 9806 9789 3355 8056\n2\n6984 1961\n', '2\n6\n1241 4641 9761 8814 9899 8114\n5\n8046 6991 5662 5409 6702\n', '3\n7\n739 5374 8768 32 9461 573 5651\n2\n5257 317\n7\n6955 3011 5115 1956 6409 6336 1273\n', '2\n7\n5714 8923 160 6811 3955 1061 8566\n6\n2850 4189 105 8610 24 3646\n', '4\n3\n6406 9469 609\n6\n4311 8222 9077 3684 2250 1727\n5\n3171 5171 2534 4105 4480\n7\n5331 4508 1020 438 3971 1817 7549\n', '4\n4\n1792 2693 4817 319\n2\n6329 5664\n9\n5159 7969 5426 9503 3958 6162 5096 6833 4053\n8\n6432 2358 6765 1586 1712 3662 9213 1270\n', '2\n6\n6645 7414 8637 7043 1874 913\n8\n4901 2634 9663 8123 3908 3190 2279 9218\n', '2\n10\n6767 9692 3341 5086 6944 2641 952 9480 7646 9841\n9\n9096 1609 2027 9493 474 3993 865 3025 2581\n', '3\n3\n4915 2698 6834\n8\n5528 4263 9546 9680 610 795 4014 6279\n10\n3401 5107 5217 9027 6267 5916 8438 2660 5828 9508\n', '5\n8\n879 1409 2082 8850 1837 5480 7041 1737\n8\n1374 830 7849 5733 1110 9484 2432 6806\n9\n7185 6173 299 4571 6305 6580 5810 3564 2278\n8\n8813 6255 7568 82 6160 9507 1775 2630\n7\n9580 3276 4583 9804 1088 2462 8953\n', '5\n4\n7517 3812 2591 6679\n4\n1224 3216 3599 5627\n9\n3387 9405 8132 3086 2165 2937 1216 9919 7595\n4\n7547 3220 4891 448\n4\n2637 8475 7939 6628\n', '3\n8\n2523 1140 1952 3551 5554 2803 9919 2168\n9\n4113 3062 3306 8465 9606 8951 6042 3234 7319\n9\n841 4700 9747 2190 4611 5974 8079 3690 710\n', '4\n5\n4385 5792 4418 1415 6155\n3\n764 1393 876\n3\n8585 1313 4974\n8\n8630 6598 589 1788 298 4589 5359 6605\n', '2\n6\n6579 9986 1031 5071 7100 6677\n10\n1779 618 2105 7450 2736 6960 5393 2612 7427 1017\n', '4\n5\n6944 6599 5768 2090 5693\n7\n9519 9362 2192 5764 1444 2901 6415\n8\n9271 9517 5640 1871 9345 4071 3138 4933\n3\n6892 3369 3986\n', '2\n9\n8098 9424 6039 3351 7504 3278 4777 4989 1993\n6\n2943 8728 5711 6984 1021 843\n', '4\n10\n6412 500 6436 3647 9101 2865 3975 3998 6245 5441\n2\n7379 4983\n4\n835 6609 2708 5821\n3\n4714 883 3593\n', '5\n2\n9913 3135\n4\n7512 3983 5252 1066\n9\n8391 581 770 1730 110 7902 5769 9506 2980\n5\n1507 6086 4494 4194 5035\n9\n7541 358 4278 9828 1743 8189 6119 6484 7354\n']
REFERENCE_SOURCE = 'import sys\n\ndef find_lca_of_two(a, b):\n    """查找两个节点 a 和 b 的最近公共祖先"""\n    while a != b:\n        if a > b:\n            a //= 2  # 较大者向上爬\n        else:\n            b //= 2  # 较大者向上爬\n    return a\n\ndef solve():\n    # 使用 sys.stdin.read().split() 处理所有空格/换行符分割的输入\n    input_data = sys.stdin.read().split()\n    if not input_data:\n        return\n    \n    ptr = 0\n    t_str = input_data[ptr]\n    ptr += 1\n    t = int(t_str)\n    \n    for _ in range(t):\n        n = int(input_data[ptr])\n        ptr += 1\n        \n        # 读取当前组的 n 个节点\n        nodes = []\n        for _ in range(n):\n            nodes.append(int(input_data[ptr]))\n            ptr += 1\n            \n        if not nodes:\n            continue\n        \n        # 迭代处理：先取第一个数作为初始 LCA，然后不断与后面的数求 LCA\n        res_lca = nodes[0]\n        for i in range(1, n):\n            res_lca = find_lca_of_two(res_lca, nodes[i])\n        \n        # 输出结果\n        print(res_lca)\n\nif __name__ == "__main__":\n    solve()\n'
assert CASES[0] == SAMPLE_IN
random.seed(5804)
def solve_reference(content):
    with tempfile.NamedTemporaryFile("w", suffix=".py", encoding="utf-8") as handle:
        handle.write(REFERENCE_SOURCE); handle.flush()
        result = subprocess.run(["python3", handle.name], input=content, text=True, capture_output=True, timeout=5, check=True)
    return result.stdout
assert solve_reference(SAMPLE_IN).split() == SAMPLE_OUT.split()
root = Path(__file__).parent / "data"
for index, content in enumerate(CASES):
    (root / f"{index}.in").write_text(content, encoding="utf-8")
    (root / f"{index}.out").write_text(solve_reference(content), encoding="utf-8")
